/// <summary>
/// table NDXSNAllianceClients
/// </summary>
public class NDXSNAllianceClients extends common
{
}

Method.Source:
/// <summary>
/// gets the client group name for a certain client
/// </summary>
/// <returns>AVAClientGroupName</returns>
public AVAClientGroupName getClientGroupNameForClient()
{
    NDXSNClientGroup2Client cG2CRecord      = NDXSNClientGroup2Client::findClientsRecId(this.RecId);
    AVAClientGroupName      clientGroupName = NDXSNClientGroup::findRecId(cG2CRecord.RefRecId_ClientGroup).ClientGroupName;

    return clientGroupName;
}

/// <summary>
/// init fields with DirPartyTable records
/// </summary>
/// <param name = "_partyTable">DirPartyTable</param>
public void initParty(DirPartyTable _partyTable)
{
    this.DirPartyName   = _partyTable.Name;
    this.DirPartyNumber = _partyTable.PartyNumber;
    this.PartyRefRecId = _partyTable.RecId;
}

/// <summary>
/// display method for client group name
/// </summary>
/// <returns>AVAClientGroupName</returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVAClientGroupName displayClientGroupName()
{
    return this.getClientGroupNameForClient();
}

/// <summary>
/// finds a NDXSNAllianceClients record for provided DirPartyNumber and AVATOSId
/// </summary>
/// <param name = "_partyNumber">DirPartyNumber</param>
/// <param name = "_companys">NDXCompanys</param>
/// <param name = "_tosId">AVATOSId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXSNAllianceClients</returns>
public static NDXSNAllianceClients findPartyTOS(
    DirPartyNumber  _partyNumber,
    NDXCompanys     _companys,
    AVATOSId        _tosId,
    boolean         _selectForUpdate = false)
{
    NDXSNAllianceClients allianceClients;

    if(_selectForUpdate)
    {
        allianceClients.selectForUpdate(_selectForUpdate);
    }

    select firstonly allianceClients
        where allianceClients.DirPartyNumber    == _partyNumber
            && allianceClients.Companys         == _companys
            && allianceClients.TOSId            == _tosId;

    return allianceClients;
}

/// <summary>
/// checks if a records exists in NDXSNAllianceClients with provided TOSId and PartyNumber
/// </summary>
/// <param name = "_partyNumber">DirPartyNumber</param>
/// <param name = "_companys">NDXCompanys</param>
/// <param name = "_tosId">AVATOSId</param>
/// <returns>boolean</returns>
public static boolean existsRecordPartyTOS(
    DirPartyNumber  _partyNumber,
    NDXCompanys     _companys,
    AVATOSId        _tosId)
{
    return NDXSNAllianceClients::findPartyTOS(_partyNumber, _companys, _tosId).RecId;
}

/// <summary>
/// creates new NDXSNAllianceClients records for not yet existing Party records in provided TOS
/// </summary>
/// <param name = "_tosId">AVATOSId</param>
public static void populateClientsForTOSId(AVATOSId _tosId)
{
    NDXSNAllianceClients    allianceClients;
    NDXSNCompanys           allianceCompanys;
    DirPartyTable           dirParty;
    CustTable               custTable;

    //ttsbegin;
    while select crosscompany custTable
        join allianceCompanys
            where allianceCompanys.TOSId == _tosId
        join dirParty
        order by dirParty.PartyNumber
        where custTable.Party == dirParty.RecId
        && custTable.DataAreaId == allianceCompanys.CompanyId
    {


        if(NDXSNAllianceClients::existsRecordPartyTOS(dirParty.PartyNumber, NDXHelperCommon::CompanyId2NDXCompany(CustTable.company()), _tosId)
            || !custTable.avaIsPartofTOSId(_tosId))
        {
            continue;
        }

        allianceClients.clear();

        allianceClients.initParty(dirParty);
        allianceClients.TOSId           = _tosId;
        allianceClients.Companys        = NDXHelperCommon::CompanyId2NDXCompany(CustTable.company());
        allianceClients.Child           = custTable.AccountNum;
        allianceClients.Determined      = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());


        allianceClients.insert();
        //insertList.add(allianceClients);
    }

    //insertList.insertDatabase();
    //ttscommit;

}

