/// <summary>
/// delete method
/// </summary>
public void delete()
{
    RecId locRecId = this.RecId;

    super();

    this.deleteClientGroupConnection(locRecId);
}

/// <summary>
/// deletes the related record in NDXSNClientGroup2Client
/// </summary>
/// <param name = "_recId">RecId</param>
public void deleteClientGroupConnection(RecId _recId)
{
    NDXSNClientGroup2Client cg2cRecord = NDXSNClientGroup2Client::findClientsRecId(_recId, true);

    if(cg2cRecord.RecId)
    {
        ttsbegin;
        cg2cRecord.delete();
        ttscommit;
    }
}

/// <summary>
/// finds a NDXSNAllianceClients record for provided Chil and AVATOSId
/// </summary>
/// <param name = "_child">alliance</param>
/// <param name = "_companys">NDXCompanys</param>
/// <param name = "_tosId">AVATOSId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXSNAllianceClients</returns>
public static NDXSNAllianceClients findTosIdChild(
    AVAAllianceClient  _child,
    NDXCompanys     _companys,
    AVATOSId        _tosId,
    boolean         _selectForUpdate = false)
{
    NDXSNAllianceClients allianceClients;

    if(_selectForUpdate)
    {
        allianceClients.selectForUpdate(_selectForUpdate);
    }

    select firstonly allianceClients
        where allianceClients.Child    == _child
            && allianceClients.Companys         == _companys
            && allianceClients.TOSId            == _tosId;

    return allianceClients;
}
